"use strict";(globalThis.webpackChunkgrc||=[]).push([[24899],{51857(e){e.exports=JSON.parse('[{"citeKey":"pawar2026gnnpress","slug":"pawar-2026-gnns-beyond-hbm-3f56","title":"GNNs Beyond HBM: Compressed, Bit-Exact Feature Streaming for Out-of-Core Training","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost258&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"pawar2026acropolis","slug":"pawar-2026-acropolis-1f2a","title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/pawar-2026-acropolis-1f2a.pdf"},"tags":["Semantic Search","LLM Agents","HPC","Model Context Protocol"],"_projectIds":["iowarp","labios"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2026semanticsearch","slug":"pawar-2026-semantic-search-agent-discovery-577f","title":"Benchmarking the Performance of Semantic Search Techniques for Agent Discovery","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Semantic_Search_Poster%20-%20Rajni%20Pawar.pdf"},"_projectIds":["hermes","iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2025tokenization","slug":"pawar-2025-scaling-data-tokenization-118b","title":"Scaling Data Tokenization for AI Systems","authors":["R. Pawar","L. Logan","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"}]')}}]);